// 1. Trích xuất dữ liệu từ Webhook (hỗ trợ cả dạng body hoặc root json)
const inputData = $input.first().json.body || $input.first().json;

const ticketId = inputData.ticketId ? String(inputData.ticketId).trim() : null;
const title = inputData.title ? String(inputData.title).trim() : null;
const description = inputData.description ? String(inputData.description).trim() : null;

// 2. Validate dữ liệu đầu vào bắt buộc
const errors = [];
if (!ticketId) errors.push("Thiếu trường bắt buộc: 'ticketId'");
if (!title) errors.push("Thiếu trường bắt buộc: 'title'");
if (!description) errors.push("Thiếu trường bắt buộc: 'description'");

if (errors.length > 0) {
  throw new Error(`[Input Validation Error] ${errors.join(' | ')}`);
}

// 3. Trả về dữ liệu đã được chuẩn hóa
return {
  ticketId,
  title,
  description,
  receivedAt: new Date().toISOString()
};

