// 1. Lấy thông tin ticket ban đầu từ node Validate & Prepare Input
const prevInput = $('Validate & Prepare Input').first().json;

// 2. Lấy kết quả thô từ AI (Hỗ trợ định dạng response từ Gemini API, OpenAI hoặc chuỗi text)
const aiResponse = $input.first().json;
let rawContent = '';

if (aiResponse.candidates && aiResponse.candidates[0]?.content?.parts?.[0]?.text) {
  // Response từ Gemini REST API
  rawContent = aiResponse.candidates[0].content.parts[0].text;
} else if (aiResponse.choices && aiResponse.choices[0]?.message?.content) {
  // Response từ OpenAI REST API
  rawContent = aiResponse.choices[0].message.content;
} else if (typeof aiResponse === 'string') {
  rawContent = aiResponse;
} else if (aiResponse.category && aiResponse.priority) {
  rawContent = JSON.stringify(aiResponse);
} else {
  rawContent = JSON.stringify(aiResponse);
}

// 3. Làm sạch markdown backticks nếu có
rawContent = rawContent.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();

// 4. Parse JSON với try/catch an toàn
let parsed = {};
try {
  parsed = JSON.parse(rawContent);
} catch (err) {
  // Fallback an toàn nếu AI trả về chuỗi lỗi
  parsed = {
    category: "Other",
    priority: "Medium",
    assignedTeam: "IT General",
    reason: "AI output was not valid JSON, defaulted to safe fallback."
  };
}

// 5. Chuẩn hóa & Validate danh mục hợp lệ
const validCategories = ["Hardware", "Software", "Network", "Account", "Other"];
const validPriorities = ["Low", "Medium", "High", "Critical"];

let category = validCategories.includes(parsed.category) ? parsed.category : "Other";
let priority = validPriorities.includes(parsed.priority) ? parsed.priority : "Medium";

// 6. Ép chuẩn Routing Table chính xác 100%
const routingTable = {
  "Hardware": "Hardware Support",
  "Software": "Software Support",
  "Network": "Network Support",
  "Account": "Account Support",
  "Other": "IT General"
};

const assignedTeam = routingTable[category] || "IT General";
const reason = parsed.reason || `Auto-classified into ${category} with ${priority} priority.`;

// 7. Trả về output hoàn chỉnh để cập nhật MongoDB và gửi Telegram
return {
  ticketId: prevInput.ticketId,
  title: prevInput.title,
  description: prevInput.description,
  category,
  priority,
  assignedTeam,
  reason,
  processedAt: new Date().toISOString()
};

